import{z as B,x as A,o as t,c as d,q as n,j as s,D as e,d as r,s as l,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"聚类标准误","description":"","frontmatter":{"title":"聚类标准误","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/clustered-se.md","filePath":"econ/clustered-se.md","lastUpdated":1791413859000}'),p={name:"econ/clustered-se.md"};function u(c,a,h,m,C,g){const o=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=n('<h1 id="聚类标准误" tabindex="-1">聚类标准误 <a class="header-anchor" href="#聚类标准误" aria-label="Permalink to &quot;聚类标准误&quot;">​</a></h1><div class="epigraph"><p>同一聚类里的观测可以任意相关；聚类标准误只要求聚类之间近似独立。把一家企业二十年当成二十个独立点，显著性几乎一定虚高。</p><footer>—— Liang and Zeger 广义估计方程传统；Cameron, Gelbach and Miller, Review of Economics and Statistics 2008；Bertrand, Duflo and Mullainathan, QJE 2004；对照 Angrist and Pischke 第 8 章</footer></div><p><a href="/econ/hac-heteroskedasticity">上一课</a>用 White 修独立截面的异方差，用 Newey–West 修<strong>一条</strong>序列的短记忆。本课缺口是面板与重复抽样：误差在同一企业、同一县、同一学校里相关，但不同聚类之间可以近似独立。把 \\(N\\times T\\) 格点当 \\(NT\\) 个 i.i.d.，或只开 robust 不开 cluster，SE 系统性偏小。识别下一课才回到<a href="/econ/ovb-measurement-error">遗漏变量与测量误差</a>；本课把推断钉在「冲击发生的那一层」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>聚类 \\(g\\) 内允许 \\(\\mathrm{Cov}(u_{gi},u_{gj})\\neq 0\\)，组间 \\(g\\neq h\\) 则协方差为零。有效信息量接近聚类个数 \\(G\\)，不是行数 \\(N\\)。五十个州的政策回归，名义样本可以是州–年几千行，\\(G=50\\) 才是渐近的分母。Bertrand–Duflo–Mullainathan 演示：州级 DiD 若忽略序列相关，\\(t\\) 统计量严重膨胀。缺口不是再选一次核带宽，而是：<strong>相关块的边界在哪，以及 \\(G\\) 不够大时正态近似还能否用。</strong></p><p><span class="marginnote">这里的「聚类」不是机器学习里的聚类算法，只是「捆成一束的观测块」：同一企业、同一县、同一学校的样本算一束。它做的事只有一件——承认束内样本不独立，别让束内的重复信息冒充更多证据。</span></p><h3 id="聚类不是越细越好" tabindex="-1">聚类不是越细越好 <a class="header-anchor" href="#聚类不是越细越好" aria-label="Permalink to &quot;聚类不是越细越好&quot;">​</a></h3><p>把聚类拆到个体，等于回到 White：组内相关被假装切碎。把聚类升到「全世界一年一个簇」，\\(G\\) 太小，CRVE 自己也不稳。层级应对准<strong>赋值或冲击的共同来源</strong>：政策在县，就县聚类；共同宏观冲击再加时间维，才考虑双向。乱聚到「看起来相关的一切」，是把设计语言换成相关图。</p><p><span class="marginnote">Abadie–Athey–Imbens–Wooldridge 强调：聚类应对准设计（哪些单位被政策或被抽样绑在一起），不是把所有显著的组内相关都收进 SE 配方。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>聚类稳健协方差（cluster-robust / Liang–Zeger）把每个 \\(g\\) 的 \\(X_g&#39;\\hat u_g\\hat u_g&#39;X_g\\) 整块加总，再夹进 \\((X&#39;X)^{-1}\\) 两边。组内相关结构不必参数化——这是它相对随机效应 GLS 的便宜之处。面板企业固定效应：默认企业聚类；州政策：州聚类。双向聚类用 Cameron–Gelbach–Miller 的公式，要求两个方向的簇都足够多。</p><p>\\(G\\) 很小（常见口诀：少于约 50）时，渐近 \\(t\\) 仍偏乐观。补救：wild cluster bootstrap（Rademacher 权重乘残差，保留簇结构）、或把推断改成随机化 / 置换——后者是另一套逻辑，本课只标出口。</p>',12)),(t(),s(i,null,{default:e(()=>[l(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20HAC%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E7%8B%AC%E7%AB%8B%E6%88%96%E5%8D%95%E5%BA%8F%E5%88%97%22%5D%20--%3E%20PANEL%5B%22%E7%BB%84%E5%86%85%E4%BB%BB%E6%84%8F%E7%9B%B8%E5%85%B3%22%5D%0A%20%20PANEL%20--%3E%20Q%5B%22%E5%86%B2%E5%87%BB%E5%85%B1%E5%90%8C%E5%8F%91%E7%94%9F%E5%9C%A8%E5%93%AA%E4%B8%80%E5%B1%82%22%5D%0A%20%20Q%20--%3E%20G%5B%22%E9%80%89%E5%AE%9A%E8%81%9A%E7%B1%BB%E5%8D%95%E4%BD%8D%22%5D%0A%20%20G%20--%3E%20CR%5B%22cluster-robust%20%E5%8D%8F%E6%96%B9%E5%B7%AE%22%5D%0A%20%20CR%20--%3E%20BIG%7B%22G%20%E6%98%AF%E5%90%A6%E5%A4%9F%E5%A4%A7%22%7D%0A%20%20BIG%20--%3E%7C%22%E6%98%AF%22%7C%20T%5B%22%E6%B8%90%E8%BF%91%20t%22%5D%0A%20%20BIG%20--%3E%7C%22%E5%90%A6%22%7C%20WB%5B%22wild%20cluster%20bootstrap%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"不平衡聚类——少数簇特别大——会让 CRVE 低估方差。报告 \\(G\\)、最大簇份额，比只报「已经 cluster」更诚实。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是承认：一次共同冲击打在整个 \\(g\\) 上，不能靠多一行观测把这次冲击「平均掉」。三明治中间从 \\(\\sum_i \\hat u_i^2 x_i x_i'\\) 变成 \\(\\sum_g\\)（簇得分外积）。\\(G\\to\\infty\\) 才是一致性的渐近；行数 \\(N\\to\\infty\\) 而 \\(G\\) 固定，聚类 SE 并不自动对。这与上一课 HAC 的 \\(T\\to\\infty\\) 是同一类「依赖单位个数」故事，只是依赖单位从时间换成了簇。",-1)),(t(),s(i,null,{default:e(()=>[l(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SH%5B%22%E4%B8%80%E6%AC%A1%E5%85%B1%E5%90%8C%E5%86%B2%E5%87%BB%E6%89%93%E5%9C%A8%E6%95%B4%E5%AE%B6%E4%BC%81%E4%B8%9A%E4%B8%8A%22%5D%20--%3E%20COR%5B%22%E8%AF%A5%E4%BC%81%E4%B8%9A%2020%20%E5%B9%B4%E8%AF%AF%E5%B7%AE%E5%90%8C%E6%B6%A8%E5%90%8C%E8%B7%8C%22%5D%0A%20%20COR%20--%3E%20WRONG%5B%22%E8%8B%A5%E5%BD%93%E6%88%90%2020%20%E4%B8%AA%E7%8B%AC%E7%AB%8B%E7%82%B9%22%5D%0A%20%20WRONG%20--%3E%20SE%5B%22SE%20%E6%8C%89%E8%A1%8C%E6%95%B0%E7%BC%A9%E5%B0%8F%EF%BC%8C%E8%A2%AB%E4%BD%8E%E4%BC%B0%22%5D%0A%20%20SE%20--%3E%20T%5B%22t%20%E7%BB%9F%E8%AE%A1%E9%87%8F%E8%86%A8%E8%83%80%22%5D%0A%20%20T%20--%3E%20SIG%5B%22%E5%81%87%E6%98%BE%E8%91%97%22%5D%0A%20%20COR%20--%3E%20RIGHT%5B%22%E6%8C%89%201%20%E4%B8%AA%E7%B0%87%E6%95%B4%E5%9D%97%E5%8A%A0%E6%80%BB%E8%AF%AF%E5%B7%AE%22%5D%0A%20%20RIGHT%20--%3E%20OK%5B%22SE%20%E5%8F%8D%E6%98%A0%E7%9C%9F%E5%AE%9E%E4%B8%8D%E7%A1%AE%E5%AE%9A%E6%80%A7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p>固定效应吸掉簇内时不变均值，<strong>不</strong>吸掉簇内时变相关。开了企业 FE 仍要企业聚类，两句话不互相替代。</p><p><span class="marginnote">直觉算一笔账：50 家企业各 20 年共 1000 行，听起来样本很大；但若全行业同一年被同一次衰退打到，这 1000 行里关于「衰退」的信息其实只有一次。SE 的有效分母接近 50 而不是 1000——报 t 值时忘掉这一点，星号就是自己送给自己的。</span></p><p><span class="marginnote">初学者容易以为「开了企业固定效应就处理掉了组内相关」。FE 只吸掉簇内不随时间变化的均值，冲击本身仍然逐年相关。所以 FE 和聚类要同时开：FE 管均值的漏，聚类 SE 管相关的漏，二者各堵各的。</span></p><p><span class="marginnote">Miller 等人后来的警告：少量大簇、处理几乎只发生在几个簇里时，CRVE 与 bootstrap 都可能失效。这时要回到设计：有效对照到底有几个。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>聚类救不了识别：簇内 \\(X\\) 与 \\(u\\) 仍可一起动，那是<a href="/econ/ovb-measurement-error">遗漏变量</a>的事。空间相关若跨过你画的边界，「簇间独立」失败，要更高一层或空间 HAC。量化栏公司金融里双向聚类更常见，本课不重写那些表，也不进限价簿。后课<a href="/econ/bootstrap-econ">Bootstrap</a>会把 wild cluster 写成一般重抽样装置；这里只为 \\(G\\) 小留一个入口。</p><p>后课默认：政策在哪一层赋值，SE 就聚到那一层；写下 \\(G\\)。下一课从推断回到外生失败的两条经典形状。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>组内可任意相关、组间独立：有效 \\(N\\) 接近 \\(G\\)。</li><li>聚类层级对准冲击，不是越细越「稳健」。</li><li>\\(G\\) 小时渐近 \\(t\\) 偏乐观，考虑 wild cluster bootstrap。</li><li>FE 不替代聚类；聚类不替代外生。</li><li>出处：Bertrand, Duflo and Mullainathan, <em>QJE</em> 2004；Cameron, Gelbach and Miller, <em>ReStat</em> 2008；Angrist and Pischke；Wooldridge。</li></ul>',9))])}const f=B(p,[["render",u]]);export{_ as __pageData,f as default};
